        "reading": "\u3057\u3085\u304F\u3060\u3044\u306F \u307E\u3060 \u304A\u308F\u3063\u3066\u3044\u307E\u305B\u3093\u3002",
        "mongolian": "\u0413\u044D\u0440\u0438\u0439\u043D \u0434\u0430\u0430\u043B\u0433\u0430\u0432\u0430\u0440 \u0445\u0430\u0440\u0430\u0430\u0445\u0430\u043D \u0434\u0443\u0443\u0441\u0430\u0430\u0433\u04AF\u0439."
