        "reading": "\u3084\u3059\u3044\u3067\u3059\u3002\u3057\u304B\u3057\u3001\u3075\u308B\u3044\u3067\u3059\u3002",
        "mongolian": "\u0425\u044F\u043C\u0434. \u0413\u044D\u0445\u0434\u044D\u044D \u0445\u0443\u0443\u0447\u0438\u043D."
