        "reading": "\u306B\u307B\u3093\u3078 \u3044\u3063\u305F\u3053\u3068\u304C \u3042\u308A\u307E\u3059\u3002",
        "mongolian": "\u042F\u043F\u043E\u043D \u0440\u0443\u0443 \u04E9\u043C\u043D\u04E9 \u043D\u044C \u044F\u0432\u0436 \u0431\u0430\u0439\u0441\u0430\u043D."
