        "reading": "\u3054\u306F\u3093\u3092 \u305F\u3079\u3066\u304B\u3089 \u3079\u3093\u304D\u3087\u3046\u3057\u307E\u3059\u3002",
        "mongolian": "\u0425\u043E\u043E\u043B \u0438\u0434\u0441\u044D\u043D\u0438\u0439 \u0434\u0430\u0440\u0430\u0430 \u0445\u0438\u0447\u044D\u044D\u043B\u043B\u044D\u043D\u044D."
