        "reading": "\u3053\u3053\u3067 \u305F\u3070\u3053\u3092 \u3059\u3063\u3066\u306F \u3044\u3051\u307E\u305B\u3093\u3002",
        "mongolian": "\u042D\u043D\u0434 \u0442\u0430\u043C\u0445\u0438 \u0442\u0430\u0442\u0430\u0436 \u0431\u043E\u043B\u043E\u0445\u0433\u04AF\u0439."
