        "japanese": "\u53CB\u9054\u3068\u8A71\u3057\u307E\u3059\u3002",
        "reading": "\u3068\u3082\u3060\u3061\u3068 \u306F\u306A\u3057\u307E\u3059\u3002",
        "mongolian": "\u041D\u0430\u0439\u0437\u0442\u0430\u0439\u0433\u0430\u0430 \u044F\u0440\u0438\u043B\u0446\u0430\u043D\u0430."
