        "reading": "\u3057\u3085\u304F\u3060\u3044\u3092 \u3057\u306A\u3051\u308C\u3070 \u3044\u3051\u307E\u305B\u3093\u3002",
        "mongolian": "\u0413\u044D\u0440\u0438\u0439\u043D \u0434\u0430\u0430\u043B\u0433\u0430\u0432\u0440\u0430\u0430 \u0445\u0438\u0439\u0445 \u0451\u0441\u0442\u043E\u0439."
