        "reading": "\u3079\u3093\u304D\u3087\u3046\u3057\u305F\u306E\u306B\u3001\u308F\u3059\u308C\u307E\u3057\u305F\u3002",
        "mongolian": "\u0425\u0438\u0447\u044D\u044D\u043B\u043B\u044D\u0441\u044D\u043D \u0447 \u043C\u0430\u0440\u0442\u0447\u0438\u0445\u0441\u0430\u043D."
