        "japanese": "\u5148\u751F\u306B\u4F5C\u6587\u3092\u898B\u3066\u3082\u3089\u3044\u307E\u3057\u305F\u3002",
        "reading": "\u305B\u3093\u305B\u3044\u306B \u3055\u304F\u3076\u3093\u3092 \u307F\u3066\u3082\u3089\u3044\u307E\u3057\u305F\u3002",
        "mongolian": "\u0411\u0430\u0433\u0448\u0430\u0430\u0440 \u0437\u043E\u0445\u0438\u043E\u043D \u0431\u0438\u0447\u043B\u044D\u0433\u044D\u044D \u0448\u0430\u043B\u0433\u0443\u0443\u043B\u0441\u0430\u043D."
