        "reading": "\u3089\u3044\u306D\u3093 \u306B\u307B\u3093\u3078 \u3044\u3053\u3046\u3068 \u304A\u3082\u3044\u307E\u3059\u3002",
        "mongolian": "\u0418\u0440\u044D\u0445 \u0436\u0438\u043B \u042F\u043F\u043E\u043D \u044F\u0432\u0430\u0445 \u0431\u043E\u0434\u043E\u043B\u0442\u043E\u0439."
