    "pattern": "\u305C\u3072",
    "mongolian": "\u0437\u0430\u0430\u0432\u0430\u043B; \u0437\u0430\u0439\u043B\u0448\u0433\u04AF\u0439; \u04AF\u043D\u044D\u0445\u044D\u044D\u0440",
