        "reading": "\u308F\u305F\u3057\u306F \u3051\u3063\u3057\u3066 \u3042\u304D\u3089\u3081\u307E\u305B\u3093\u3002",
        "mongolian": "\u0411\u0438 \u0445\u044D\u0437\u044D\u044D \u0447 \u0431\u0443\u0443\u0436 \u04E9\u0433\u04E9\u0445\u0433\u04AF\u0439."
