    "pattern": "\u3066\u306F\u3058\u3081\u3066",
    "mongolian": "~\u0441\u043D\u044B \u0434\u0430\u0440\u0430\u0430 \u043B \u0430\u043D\u0445",
    "explanation": '\u042D\u043D\u044D\u0445\u04AF\u04AF N3 \u0442\u04AF\u0432\u0448\u043D\u0438\u0439 \u0434\u04AF\u0440\u044D\u043C \u043D\u044C "~\u0441\u043D\u044B \u0434\u0430\u0440\u0430\u0430 \u043B \u0430\u043D\u0445" \u0433\u044D\u0441\u044D\u043D \u0443\u0442\u0433\u044B\u0433 \u0438\u043B\u044D\u0440\u0445\u0438\u0439\u043B\u043D\u044D.',
    "usage": "[\u3066\u306F\u3058\u3081\u3066] \u0445\u044D\u043B\u0431\u044D\u0440\u0438\u0439\u0433 \u04E9\u0433\u04AF\u04AF\u043B\u0431\u044D\u0440\u0442 \u0430\u0448\u0438\u0433\u043B\u0430\u0445 \u043D\u044C: ~\u0441\u043D\u044B \u0434\u0430\u0440\u0430\u0430 \u043B \u0430\u043D\u0445",
    "structure": "\u3066\u306F\u3058\u3081\u3066",
    "examples": [
      {
        "japanese": "\u65E5\u672C\u306B\u6765\u3066\u306F\u3058\u3081\u3066\u3001\u96EA\u3092\u898B\u307E\u3057\u305F\u3002",
        "reading": "\u306B\u307B\u3093\u306B \u304D\u3066 \u306F\u3058\u3081\u3066\u3001\u3086\u304D\u3092 \u307F\u307E\u3057\u305F\u3002",
        "mongolian": "\u042F\u043F\u043E\u043D\u0434 \u0438\u0440\u0441\u043D\u0438\u0439 \u0434\u0430\u0440\u0430\u0430 \u043B \u0430\u043D\u0445 \u0446\u0430\u0441 \u04AF\u0437\u0441\u044D\u043D."
      }
    ],
    "jlptLevel": "N3",
    "createdAt": "2026-09-02T00:00:00.000Z"
