    "pattern": "\u9006\u306B\uFF08\u304E\u3083\u304F\u306B\uFF09",
    "mongolian": "\u044D\u0441\u0440\u044D\u0433\u044D\u044D\u0440\u044D\u044D; \u0445\u0430\u0440\u0438\u043D \u0447",
    "explanation": '\u042D\u043D\u044D\u0445\u04AF\u04AF N2 \u0442\u04AF\u0432\u0448\u043D\u0438\u0439 \u0434\u04AF\u0440\u044D\u043C \u043D\u044C "\u044D\u0441\u0440\u044D\u0433\u044D\u044D\u0440\u044D\u044D; \u0445\u0430\u0440\u0438\u043D \u0447" \u0433\u044D\u0441\u044D\u043D \u0443\u0442\u0433\u044B\u0433 \u0438\u043B\u044D\u0440\u0445\u0438\u0439\u043B\u043D\u044D.',
    "usage": "[\u9006\u306B\uFF08\u304E\u3083\u304F\u306B\uFF09] \u0445\u044D\u043B\u0431\u044D\u0440\u0438\u0439\u043D \u0445\u044D\u0440\u044D\u0433\u043B\u044D\u044D: \u044D\u0441\u0440\u044D\u0433\u044D\u044D\u0440\u044D\u044D; \u0445\u0430\u0440\u0438\u043D \u0447",
    "structure": "\u9006\u306B\uFF08\u304E\u3083\u304F\u306B\uFF09",
    "examples": [
      {
        "japanese": "\u6025\u3044\u3060\u3064\u3082\u308A\u304C\u3001\u9006\u306B\u6642\u9593\u304C\u304B\u304B\u3063\u3066\u3057\u307E\u3044\u307E\u3057\u305F\u3002",
        "reading": "\u3044\u305D\u3044\u3060 \u3064\u3082\u308A\u304C\u3001\u304E\u3083\u304F\u306B \u3058\u304B\u3093\u304C \u304B\u304B\u3063\u3066 \u3057\u307E\u3044\u307E\u3057\u305F\u3002",
        "mongolian": "\u042F\u0430\u0440\u0441\u0430\u043D \u043C\u04E9\u0440\u0442\u043B\u04E9\u04E9 \u044D\u0441\u0440\u044D\u0433\u044D\u044D\u0440\u044D\u044D \u0431\u04AF\u0440 \u0438\u0445 \u0445\u0443\u0433\u0430\u0446\u0430\u0430 \u043E\u0440\u0447\u0438\u0445\u043B\u043E\u043E."
      }
    ],
    "jlptLevel": "N2",
    "createdAt": "2026-09-02T00:00:00.000Z"
