        "reading": "\u304B\u308C\u306F \u3044\u308F\u3086\u308B \u3066\u3093\u3055\u3044\u3067\u3059\u3002",
        "mongolian": "\u0422\u044D\u0440 \u0431\u043E\u043B \u0433\u044D\u0433\u0434\u044D\u0445 \u0441\u0443\u0443\u0442 \u0445\u04AF\u043D."
