        "reading": "\u3044\u3088\u3044\u3088 \u3042\u3057\u305F\u3001\u3057\u3051\u3093\u306E \u3072\u3067\u3059\u3002",
        "mongolian": "\u042D\u0446\u044D\u0441\u0442 \u043D\u044C \u043C\u0430\u0440\u0433\u0430\u0430\u0448 \u0448\u0430\u043B\u0433\u0430\u043B\u0442\u044B\u043D \u04E9\u0434\u04E9\u0440."
