    "mongolian": "...\u0445 \u0451\u0441\u0433\u04AF\u0439; ... \u0437\u04AF\u0439\u043B \u0431\u0438\u0448",
    "explanation": '\u042D\u043D\u044D\u0445\u04AF\u04AF N2 \u0442\u04AF\u0432\u0448\u043D\u0438\u0439 \u0434\u04AF\u0440\u044D\u043C \u043D\u044C "...\u0445 \u0451\u0441\u0433\u04AF\u0439; ... \u0437\u04AF\u0439\u043B \u0431\u0438\u0448" \u0433\u044D\u0441\u044D\u043D \u0443\u0442\u0433\u044B\u0433 \u0438\u043B\u044D\u0440\u0445\u0438\u0439\u043B\u043D\u044D.',
    "usage": "[\u3082\u306E\u3067\u306F\u306A\u3044] \u0445\u044D\u043B\u0431\u044D\u0440\u0438\u0439\u043D \u0445\u044D\u0440\u044D\u0433\u043B\u044D\u044D: ...\u0445 \u0451\u0441\u0433\u04AF\u0439; ... \u0437\u04AF\u0439\u043B \u0431\u0438\u0448",
    "structure": "\u3082\u306E\u3067\u306F\u306A\u3044",
    "examples": [
      {
        "japanese": "\u4EBA\u306E\u60AA\u53E3\u3092\u8A00\u3046\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
        "reading": "\u3072\u3068\u306E \u308F\u308B\u3050\u3061\u3092 \u3044\u3046 \u3082\u306E\u3067\u306F \u3042\u308A\u307E\u305B\u3093\u3002",
        "mongolian": "\u0425\u04AF\u043D\u0438\u0439\u0433 \u043C\u0443\u0443\u043B\u0430\u0445 \u0451\u0441\u0433\u04AF\u0439."
      }
    ],
