        "reading": "\u3057\u3083\u3063\u304D\u3093\u3057\u3066\u307E\u3067 \u305F\u304B\u3044 \u304F\u308B\u307E\u3092 \u304B\u3046 \u3072\u3064\u3088\u3046\u306F \u3042\u308A\u307E\u305B\u3093\u3002",
        "mongolian": "\u04E8\u0440 \u0442\u0430\u0432\u044C\u0442\u043B\u0430\u0430 \u04AF\u043D\u044D\u0442\u044D\u0439 \u043C\u0430\u0448\u0438\u043D \u0430\u0432\u0430\u0445 \u0448\u0430\u0430\u0440\u0434\u043B\u0430\u0433\u0430\u0433\u04AF\u0439."
