    "usage": "[\u3088\u308A\u307B\u304B\u306A\u3044] \u0445\u044D\u043B\u0431\u044D\u0440\u0438\u0439\u043D \u0445\u044D\u0440\u044D\u0433\u043B\u044D\u044D: ...-\u0430\u0430\u0441 \u04E9\u04E9\u0440 \u0430\u0440\u0433\u0430\u0433\u04AF\u0439",
    "structure": "\u3088\u308A\u307B\u304B\u306A\u3044",
    "examples": [
      {
        "japanese": "\u96FB\u8ECA\u304C\u6B62\u307E\u3063\u305F\u306E\u3067\u3001\u6B69\u3044\u3066\u5E30\u308B\u3088\u308A\u307B\u304B\u3042\u308A\u307E\u305B\u3093\u3002",
        "reading": "\u3067\u3093\u3057\u3083\u304C \u3068\u307E\u3063\u305F\u306E\u3067\u3001\u3042\u308B\u3044\u3066 \u304B\u3048\u308B\u3088\u308A \u307B\u304B \u3042\u308A\u307E\u305B\u3093\u3002",
        "mongolian": "\u0413\u0430\u043B\u0442 \u0442\u044D\u0440\u044D\u0433 \u0437\u043E\u0433\u0441\u0441\u043E\u043D \u0442\u0443\u043B \u0430\u043B\u0445\u0430\u0436 \u0445\u0430\u0440\u0438\u0445\u0430\u0430\u0441 \u04E9\u04E9\u0440 \u0430\u0440\u0433\u0430\u0433\u04AF\u0439."
      }
    ],
